const $=s=>document.querySelector(s);const versions={ory:{label:'SUPERSEDED / ILLUSTRATIVE COMPONENT ALLOCATION',title:'A stack of focused responsibilities.',intro:'The task asked for Ory components and a session/token model. It does not disclose the chosen details. The following is an illustrative design option, not a reconstruction.',flow:[['01 / BROWSER','Frontend starts a self-service identity flow.'],['02 / IDENTITY','A hypothetical Kratos setup handles identity and browser sessions.'],['03 / API','Backend validates the session and enforces a policy before returning data.']],components:[['Kratos / hypothetical','Identity lifecycle and session verification.'],['Keto / optional hypothesis','Relationship-based authorization, if the policy needs it.'],['Hydra / optional hypothesis','OAuth2/OIDC provider only if delegated token-based clients require it. Not inherently required for a cookie-session app.'],['Frontend + backend','UI presents flows; backend validates identity and permissions. Keep administrative interfaces private.']]},keycloak:{label:'REPLACEMENT PROVIDER / SOURCE-CONFIRMED NAME',title:'A later decision chose Keycloak.',intro:'The original explicitly states that Keycloak replaces Ory. It does not provide the detailed replacement protocol, session implementation or role policy.',flow:[['01 / CONFIRMED','Keycloak is the replacement provider.'],['02 / NEEDS THE AUTH SPEC','Consult the current authentication specification for frontend/backend integration.'],['03 / NEEDS IMPLEMENTATION EVIDENCE','Verify actual session/token and permission enforcement in the deployed system.']],components:[['Provider','Keycloak, as named by the superseding decision.'],['Sessions and tokens','Not detailed in this source; no assumed configuration is presented as fact.'],['Roles and permissions','Viewing and editing need defined policy; the worksheet below is an example only.'],['Integration','The task calls for updating the authentication specification. This page does not alter that specification.']]}};function provider(k){const v=versions[k];$('#providerLabel').textContent=v.label;$('#providerTitle').textContent=v.title;$('#providerIntro').textContent=v.intro;$('#flow').innerHTML=v.flow.map(x=>'<p><b>'+x[0]+'</b>'+x[1]+'</p>').join('');$('#components').innerHTML=v.components.map(x=>'<p><b>'+x[0]+'</b><br>'+x[1]+'</p>').join('');document.querySelectorAll('[data-provider]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.provider===k))}document.querySelectorAll('[data-provider]').forEach(b=>b.onclick=()=>provider(b.dataset.provider));function policy(){const r=$('#role').selectedIndex,a=$('#action').selectedIndex,allowed=r>0&&r>=a+1;$('#outcomeTitle').textContent=allowed?'Proposed policy: allow':'Proposed policy: deny';$('#outcomeText').textContent=$('#role').value+' → '+$('#action').value+'. '+(allowed?'This illustrative role includes the action.':'This illustrative role does not include the action.')+' No real authorization check was made.'}$('#role').onchange=policy;$('#action').onchange=policy;provider('ory');policy();